import {mountExperiment} from './experiment-ui.js';
import {R,C,T,B,fmt,stats,note,node,flow,table,colors,legend,strip,bars} from './computer-ui.js';
import {newPage,pageInsert,pageDelete,pageCompact,bufferAccess,layoutCost,encoding,newTree,treeInsert,treeSearch,treeLeaves,composite,lsmPut,lsmFlush,lsmRead,bloom,accessPlan,joinCost,externalSort,pagination,visibleVersion,writeSkew,reservation,redoPage,checkpointStep,pitr,vacuumVersions,compactRuns,partitionScan} from './database-models.js';
const labs={};
const tiles=(values,cls='')=>`<div class="db-tiles ${cls}">${values.map(v=>`<span>${v}</span>`).join('')}</div>`;
const run=(label,entries)=>`<div class="db-run"><span>${label}</span><div>${entries.length?entries.map(e=>`<span class="${e.value===null?'db-tombstone':''}">${e.key}: ${e.value===null?'†':e.value}<small>#${e.seq}</small></span>`).join(''):'<span class="muted">empty</span>'}</div></div>`;

labs.pages=()=>({title:'Pack a 256-byte page',state:{size:32,page:newPage()},controls:[R('size','New row payload (bytes)',8,64,8),B('insert','Insert row'),B('delete','Delete oldest live row'),B('compact','Compact page')],actions:{insert:s=>{s.page=pageInsert(s.page,s.size);},delete:s=>{s.page=pageDelete(s.page);},compact:s=>{s.page=pageCompact(s.page);}},render:s=>{
 const p=s.page,lower=16+2*p.slots.length,holes=p.slots.filter(r=>!r.live).reduce((n,r)=>n+r.size,0);
 const cells=Array.from({length:256},(_,i)=>{const row=p.slots.find(r=>r.size&&i>=r.offset&&i<r.offset+r.size);const kind=i<16?'header':i<lower?'slot':row?row.live?'live':'dead':'free';return `<span class="${kind}" title="Byte ${i}: ${row?'row '+row.id+' '+(row.live?'live':'dead'):kind}"></span>`;}).join('');
 return `<div class="db-page-map" role="img" aria-label="256 bytes: 16 header, ${p.slots.length*2} slot bytes, ${p.upper-lower} contiguous free, ${holes} reclaimable dead bytes">${cells}</div>`+legend([['Header',colors[2]],['Slots',colors[0]],['Live rows','#96d4b3'],['Dead payload',colors[4]],['Free','#273031']])+stats(['Contiguous free',`${p.upper-lower} B`],['Fragmented dead bytes',`${holes} B`],['Live / reserved slots',`${p.slots.filter(r=>r.live).length} / ${p.slots.length}`])+table(['Slot','Payload offset','Bytes','State'],p.slots.map(r=>[r.id,r.size?r.offset:'—',r.size,r.live?'live':'dead']))+note(p.message);
},foot:'Tiny slotted page: 16-byte header, 2-byte slots; payload sizes include all modeled row bytes. Dead slots remain reserved; no MVCC safety horizon or overflow pages.'});

labs.buffers=()=>({title:'Read, dirty, and evict pages',state:{page:'A',frames:[],hits:0,reads:0,writes:0,accesses:0,message:'Read A, B, C; reread A; then read D.'},controls:[C('page','Requested page',['A','B','C','D','E']),B('read','Read page'),B('write','Update page')],actions:{read:s=>Object.assign(s,bufferAccess(s,s.page)),write:s=>Object.assign(s,bufferAccess(s,s.page,true))},render:s=>{
 return `<p class="small">Three buffer frames · least recent → most recent</p><div class="db-buffer-pool">${Array.from({length:3},(_,i)=>{const f=s.frames[i];return `<div class="${f?.dirty?'dirty':''}"><small>frame ${i+1}</small><strong>${f?f.page:'—'}</strong><span>${f?f.dirty?'dirty · needs writeback':'clean':'empty'}</span></div>`;}).join('')}</div>`+flow([['Request',s.page],['Buffer pool',`${s.hits} hits`,'blue'],['Storage',`${s.reads} reads · ${s.writes} writes`,'purple']])+note(s.message)+stats(['Accesses',s.accesses],['Storage reads',s.reads],['Dirty writebacks',s.writes]);
},foot:'Cold three-frame LRU pool. Updates first read the page; dirty eviction synchronously writes it after its WAL is safe. No OS cache, pinned pages, or background writer.'});

labs.layouts=()=>({title:'Scan only the fields you need',state:{rows:10000,projected:1},controls:[R('rows','Rows scanned',1000,100000,1000),R('projected','Projected columns out of eight',1,8)],render:s=>{
 const cost=layoutCost(s.rows,8,s.projected);
 const grid=columnar=>`<div class="db-layout-grid ${columnar?'columnar':'rowstore'}" role="img" aria-label="${columnar?s.projected:'8'} columns fetched per row in this scan">${Array.from({length:64},(_,i)=>`<span class="${!columnar||i%8<s.projected?'read':''} ${i%8<s.projected?'needed':''}" title="Row ${Math.floor(i/8)+1}, field ${i%8+1}">${i%8+1}</span>`).join('')}</div>`;
 return `<div class="db-compare"><div><h3>Row layout</h3>${grid(false)}</div><div><h3>Column layout</h3>${grid(true)}</div></div>`+legend([['Needed field','#96d4b3'],['Fetched but not projected',colors[0]],['Not fetched','#273031']])+bars([['Row pages',cost.rowPages,colors[0]],['Column pages',cost.columnPages,'#96d4b3']])+note('Both scans return the same projected values. Shown: eight example rows; the counts use the selected full table size.');
},foot:'Full scan, eight 8-byte columns, 4 KiB pages, separately rounded column streams. No index, headers, compression, predicate pruning, or partially filled row metadata.'});

labs.encoding=()=>({title:'Encode the same column three ways',state:{order:'Clustered',distinct:4},controls:[C('order','Value order',['Clustered','Interleaved']),R('distinct','Distinct values',1,8)],render:s=>{
 const r=encoding(s.order,s.distinct),letters='ABCDEFGH';
 return `<p class="small">64 values · each letter stands for an eight-byte value</p><div class="db-value-grid">${r.values.map(v=>`<span style="--value-color:${colors[v%colors.length]}">${letters[v]}</span>`).join('')}</div><p class="small">Runs: value × count${r.runs.length>16?' · first 16 shown':''}</p>`+tiles(r.runs.slice(0,16).map(x=>`${letters[x.value]} × ${x.count}`))+bars([['Raw bytes',r.raw],['Dictionary bytes',r.dictionary,colors[1]],['Dictionary + runs',r.rle,'#96d4b3']])+stats(['Run count',r.runs.length],['Dictionary size',`${s.distinct*8} B`],['Run representation',`${r.runs.length*2} B`])+note('Reordering changes run lengths while keeping value frequencies fixed. At one distinct value, every arrangement is one run.');
},foot:'64 eight-byte values; dictionary IDs and run counts each use one byte. No headers, bit packing, codec CPU, or update cost.'});

const insertionKeys=[20,5,30,10,25,15,35,2,8,12,18,22,28,32,38,1,4,6,9,11,14,16,19,24];
function drawTree(tree,key){
 const leaves=treeLeaves(tree),width=Math.max(560,leaves.length*110),positions=new Map(),nodes=[],edges=[];
 let deepest=0;
 function place(n,depth){let x;if(n.leaf)x=(leaves.indexOf(n)+.5)*width/leaves.length;else{x=n.children.map(child=>place(child,depth+1)).reduce((a,b)=>a+b,0)/n.children.length;}
 const p={x,y:40+depth*85};positions.set(n,p);nodes.push(n);deepest=Math.max(deepest,depth);return x;}
 place(tree,0);const path=treeSearch(tree,key).path;
 for(const n of nodes)if(!n.leaf)for(const child of n.children){const a=positions.get(n),b=positions.get(child);edges.push(`<path d="M${a.x} ${a.y+18}L${b.x} ${b.y-18}" class="${path.includes(n)&&path.includes(child)?'selected':''}"/>`);}
 return `<div class="db-tree-scroll"><svg viewBox="0 0 ${width} ${deepest*85+95}" style="min-width:${width}px" role="img" aria-label="B plus tree, ${deepest+1} levels, lookup ${key}: ${treeSearch(tree,key).found?'found':'absent'}">${edges.join('')}${nodes.map(n=>{const p=positions.get(n);return `<g class="${path.includes(n)?'selected':''}"><rect x="${p.x-44}" y="${p.y-18}" width="88" height="36" rx="5"/><text x="${p.x}" y="${p.y+5}">${n.keys.join(' | ')||'empty'}</text></g>`;}).join('')}${leaves.slice(0,-1).map((n,i)=>{const a=positions.get(n),b=positions.get(leaves[i+1]);return `<text class="db-leaf-arrow" x="${(a.x+b.x)/2}" y="${a.y+5}">→</text>`;}).join('')}</svg></div>`;
}
labs.btree=()=>({title:'Split leaves, then split a parent',state:{tree:newTree(),n:0,key:20},controls:[R('key','Lookup key',1,40),B('insert','Insert next key'),B('finish','Insert all 24 keys')],actions:{insert:s=>{if(s.n<insertionKeys.length)s.tree=treeInsert(s.tree,insertionKeys[s.n++]);},finish:s=>{while(s.n<insertionKeys.length)s.tree=treeInsert(s.tree,insertionKeys[s.n++]);}},render:s=>{
 const result=treeSearch(s.tree,s.key);
 return `<p class="small">Next insertion: ${s.n<insertionKeys.length?insertionKeys[s.n]:'complete'} · highlighted nodes are the lookup path</p>`+drawTree(s.tree,s.key)+stats(['Keys stored',s.n],['Pages on search path',result.path.length],['Lookup result',result.found?'Found':'Absent'])+note('Insert four keys to trigger the first split. Leaves hold records; upper nodes hold routing separators. Change the lookup to follow a different path.');
},foot:'Unique integer keys, maximum three keys per node, insertion only. Arrows depict leaf order, not stored sibling pointers. No concurrency, merge, disk latency, or fill-factor policy.'});

labs.composite=()=>({title:'Choose the useful leading key',state:{order:'Tenant, day',tenant:2,day:5,cover:false,visible:true},controls:[C('order','Index key order',['Tenant, day','Day, tenant']),R('tenant','Tenant equality',1,3),R('day','Minimum day',1,8),T('cover','Include requested payload in index'),T('visible','Matching heap pages all-visible')],render:s=>{
 const r=composite(s.order,s.tenant,s.day),heap=s.cover&&s.visible?0:r.result.length;
 const scanned=e=>r.scanned.some(x=>x.tenant===e.tenant&&x.day===e.day),match=e=>e.tenant===s.tenant&&e.day>=s.day;
 return `<div class="db-sql">WHERE tenant = ${s.tenant} AND day &gt;= ${s.day}</div><div class="db-index-strip">${r.entries.map(e=>`<span class="${scanned(e)?match(e)?'match':'visited':''}"><b>${s.order==='Tenant, day'?e.tenant:e.day}</b><small>${s.order==='Tenant, day'?e.day:e.tenant}</small></span>`).join('')}</div>`+legend([['Returned','#96d4b3'],['Scanned then filtered',colors[0]],['Outside scan','#273031']])+stats(['Index entries visited',r.scanned.length],['Rows returned',r.result.length],['Heap tuple fetches',heap])+note(heap?'The query still fetches each matching heap tuple for its payload or visibility. These are tuple fetches, not necessarily distinct page reads.':'Included payload and established visibility let this toy answer without fetching matching heap tuples.');
},foot:'24 rows, simple contiguous B-tree range scan; no skip scan. PostgreSQL-style visibility gate for index-only access; included payload size and index write cost are not modeled.'});

labs.lsm=()=>({title:'Search newest to oldest',state:{key:'A',value:10,seq:0,mem:[],runs:[]},controls:[C('key','Key to write or inspect',['A','B','C']),R('value','New value',1,99),B('put','Write value'),B('delete','Write tombstone'),B('flush','Flush memtable')],actions:{put:s=>Object.assign(s,lsmPut(s,s.key,s.value)),delete:s=>Object.assign(s,lsmPut(s,s.key,null)),flush:s=>Object.assign(s,lsmFlush(s))},render:s=>{
 const r=lsmRead(s,s.key);
 return run('Memtable · newest',s.mem)+s.runs.slice(0,8).map((entries,i)=>run(`Run ${s.runs.length-i}`,entries)).join('')+(s.runs.length>8?`<p class="small">${s.runs.length-8} older runs omitted from the diagram; lookups still include them.</p>`:'')+stats(['Latest read',r.found?r.value:'Not found'],['Sources searched',r.probes],['Immutable runs',s.runs.length])+note('Write A, flush, then overwrite or delete A. The older run stays immutable, but the latest read follows the newer entry. † denotes a tombstone.');
},foot:'Latest-value reads; sequence numbers totally order writes. Flush creates a sorted run. WAL durability, snapshots, automatic flush, Bloom filters, and compaction are separate mechanisms.'});

labs.bloom=()=>({title:'Probe a membership hint',state:{bits:32,k:3,n:5,query:2,message:''},controls:[C('bits','Filter bits',['16','32','64','128']),R('k','Hash functions',1,5),R('n','Inserted integer keys 1 through…',1,12),R('query','Lookup key',1,200),B('collision','Find an absent collision')],onChange:s=>{s.message='';},actions:{collision:s=>{const keys=Array.from({length:s.n},(_,i)=>i+1);const found=Array.from({length:200-s.n},(_,i)=>s.n+i+1).find(q=>bloom(keys,+s.bits,s.k,q).maybe);if(found){s.query=found;s.message='Found a false positive in keys up to 200.';}else s.message='No absent collision in keys up to 200. Try a smaller filter or more inserted keys.';}},render:s=>{
 const keys=Array.from({length:s.n},(_,i)=>i+1),r=bloom(keys,+s.bits,s.k,s.query);
 return `<div class="db-bloom" role="img" aria-label="${r.cells.filter(Boolean).length} bits set; query ${s.query} checks ${r.positions.join(', ')}">${r.cells.map((bit,i)=>`<span class="${bit?'set':''} ${r.positions.includes(i)?'probe':''}" title="Bit ${i}${r.positions.includes(i)?' · queried':''}">${bit?1:0}</span>`).join('')}</div>`+stats(['Filter answer',r.maybe?'Maybe present':'Definitely absent'],['Underlying truth',r.present?'Present':'Absent'],['Set bits',`${r.cells.filter(Boolean).length} / ${s.bits}`])+note(s.message||(r.maybe&&!r.present?'A false positive: all required bits are set by other keys. The underlying lookup must reject this key.':r.maybe?'The filter cannot prove existence. Check the underlying key/value data.':'At least one queried bit is zero. This filter can safely skip the underlying lookup.'));
},foot:'Deterministic toy hashes; outlined cells are queried. No false negatives for inserted keys under correct use. Collision rates are not predictions for RocksDB’s filter implementation.'});

labs.plans=()=>({title:'Compare estimated and actual access cost',state:{estimated:1,actual:50,random:4},controls:[R('estimated','Estimated matching rows (%)',1,100),R('actual','Actual matching rows (%)',1,100),R('random','Cost per random visit',1,8),B('analyze','Refresh estimate to actual')],actions:{analyze:s=>{s.estimated=s.actual;}},render:s=>{
 const r=accessPlan(s.estimated,s.actual,s.random);
 return `<div class="db-plan-tree">${node('SELECT matching rows','Filter')}${node('Chosen access path',r.choice,'purple')}<div>${node('Estimated rows',`${s.estimated*100}`)}${node('Actual rows',`${s.actual*100}`,'blue')}</div></div>`+bars([['Seq. scan cost',r.scan,colors[1]],['Estimated index',r.estimatedIndex,colors[2]],['Actual index',r.actualIndex,colors[0]]])+stats(['Chosen plan cost',fmt(r.actualCost)],['Best actual cost',fmt(Math.min(r.scan,r.actualIndex))],['Estimate error factor',`${fmt(s.actual/s.estimated,2)}×`])+note('The chosen plan uses estimates. Refreshing the estimate makes this toy’s next plan use the actual distribution; real ANALYZE samples rather than knowing perfect truth.');
},foot:'10,000 rows / 1,000 pages. Index cost = 3 + matching rows × random-visit cost; sequential cost = 1,000. One uncached heap visit per match, including repeated pages; abstract units, no bitmap scan candidate.'});

labs.joins=()=>({title:'Choose how matches are found',state:{outer:10,inner:1000,indexed:true,sorted:false},controls:[R('outer','Outer rows after filtering',1,1000),R('inner','Inner rows',100,10000,100),T('indexed','Usable inner index'),T('sorted','Both inputs already sorted')],render:s=>{
 const costs=joinCost(s.outer,s.inner,s.indexed,s.sorted),best=Object.entries(costs).sort((a,b)=>a[1]-b[1])[0][0];
 return flow([['Outer',`${fmt(s.outer)} rows`],['Join on key',s.indexed?'inner index available':'no inner index','purple'],['Inner',`${fmt(s.inner)} rows`,'blue']])+bars([['Nested loop',costs.nested,colors[0]],['Hash build + probe',costs.hash,'#96d4b3'],['Merge + sorting',costs.merge,colors[1]]])+stats(['Smallest toy work',best],['Nested probes',fmt(s.outer)],['Hash build entries',fmt(s.inner)])+note('Use a tiny outer input with an indexed inner relation, then increase the outer input. Sorting can make a merge expensive unless the inputs arrive ordered.');
},foot:'Abstract operations: nested = outer × inner, or outer × (ceil(log2(inner+1)) + 1) when indexed; hash = outer + inner; merge adds n log2 n sorting unless ordered. No skew, output fanout, spills, or hardware timing.'});

labs.spills=()=>({title:'Create and merge sorted runs',state:{rows:10000,memory:1000},controls:[R('rows','Rows to sort',1000,20000,1000),R('memory','Rows that fit in memory',500,10000,500)],render:s=>{
 const r=externalSort(s.rows,s.memory);
 return `<div class="db-merge-levels">${r.levels.map((count,i)=>`<div><span>${i===0?'Initial sorted runs':`Merge pass ${i}`}</span><div>${Array.from({length:Math.min(count,16)},()=>'<i></i>').join('')}${count>16?`<small>+${count-16}</small>`:''}</div><strong>${count}</strong></div>`).join('')}</div>`+stats(['Initial runs',r.initialRuns],['Merge passes',r.passes],['Temporary row transfers',fmt(r.tempRowTransfers)])+note(r.initialRuns===1?'All rows fit in memory, so this sort does not spill.':`The final merge streams its output. Intermediate runs still account for ${fmt(r.tempRowTransfers)} temporary row reads plus writes in total.`);
},foot:'Fixed four-way merging with sufficient merge buffers; equal row widths; final output streamed. Transfer count excludes reading original input and includes full intermediate runs.'});

labs.pagination=()=>({title:'Page through a moving feed',state:{inserted:false,method:'Offset',depth:0},controls:[C('method','Next-page method',['Offset','Keyset']),T('inserted','Two newer rows arrive after page one'),R('depth','Separate cost example: rows before cursor',0,100000,1000)],render:s=>{
 const r=pagination(s.inserted,s.method),depth=s.depth??0;
 return `<div class="db-compare"><div><h3>First page</h3>${tiles(r.first)}</div><div><h3>Second page</h3><div class="db-tiles">${r.second.map(id=>`<span class="${r.duplicates.includes(id)?'duplicate':''}">${id}</span>`).join('')}</div></div></div><div class="db-sql">${s.method==='Offset'?'ORDER BY id DESC LIMIT 5 OFFSET 5':'WHERE id &lt; 96 ORDER BY id DESC LIMIT 5'}</div>`+stats(['Repeated IDs',r.duplicates.length?r.duplicates.join(', '):'None'],['Deep-page entries consumed',fmt(s.method==='Offset'?depth+5:5)],['Keyset seek',s.method==='Keyset'?'Plus tree descent':'Not used'])+note(r.duplicates.length?'The two arrivals shifted the old rows down. OFFSET repeats two IDs from page one.':'The unique immutable ID gives a stable boundary here. The cost example changes depth independently of the 20-row feed diagram.',r.duplicates.length>0);
},foot:'Descending unique immutable IDs; page size five, fresh snapshot per page. Deep cost assumes an ordered index and excludes tree descent; no deletions, mutable keys, or snapshot export.'});

labs.snapshots=()=>({title:'Read versions through a snapshot',state:{mode:'Repeatable read',clock:10,versions:[{commit:10,value:100}],last:null},controls:[C('mode','Reader isolation',['Read committed','Repeatable read']),B('commit','Other transaction commits +10'),B('read','Reader SELECT')],onChange:s=>{s.last=null;},actions:{commit:s=>{if(s.clock<60){s.clock+=10;s.versions.push({commit:s.clock,value:s.versions.at(-1).value+10});}},read:s=>{const cutoff=s.mode==='Repeatable read'?10:s.clock;s.last={...visibleVersion(s.versions,cutoff),cutoff};}},render:s=>{
 return `<div class="db-version-chain">${s.versions.map(v=>`<div class="${s.last?.commit===v.commit?'selected':''}"><small>commit ${v.commit}</small><strong>${v.value}</strong></div>`).join('<span class="op">→</span>')}</div>`+flow([['Reader snapshot',s.mode==='Repeatable read'?'fixed at 10':`next statement: ${s.clock}`],['Last SELECT',s.last?`value ${s.last.value}`:'not read','blue'],['Newest committed',s.versions.at(-1).value,'purple']])+note(s.last?`That SELECT used cutoff ${s.last.cutoff} and returned version committed at ${s.last.commit}.`:'Read, commit a new version elsewhere, then read again. Switching modes changes the modeled reader contract.');
},foot:'Committed versions only, monotonic commit-sequence abstraction. Repeatable-read snapshot is initialized at 10. No own writes, concurrent transaction-ID sets, or locking reads.'});

labs['write-skew']=()=>({title:'Spend the last two resources',state:{serial:false,step:0},controls:[T('serial','Prevent the nonserializable schedule'),B('step','Next transaction step')],onChange:s=>{s.step=0;},actions:{step:s=>{s.step=Math.min(4,s.step+1);}},render:s=>{
 const r=writeSkew(s.serial,s.step);
 return `<div class="db-transaction-lanes"><div><h3>Transaction A</h3><p class="${s.step>=1?'done':''}">1. Sees B available</p><p class="${s.step>=3?'done':''}">3. Commits A unavailable</p></div><div><h3>Transaction B</h3><p class="${s.step>=2?'done':''}">2. Sees A available</p><p class="${s.step>=4?'done':''}">4. ${s.serial?'Abort B; retry needed':'Commits B unavailable'}</p></div></div>`+stats(['Resource A',r.a?'Available':'Taken'],['Resource B',r.b?'Available':'Taken'],['At least one remains',r.a||r.b?'Yes':'NO'])+note(r.aborted?'B cannot commit this schedule. Retrying its whole transaction against the updated state lets it re-evaluate the invariant.':!r.a&&!r.b?'Both snapshot decisions looked valid. Their combined committed state breaks the invariant.':'The rule is: at least one resource must remain available. Step through both reads before either write.',!r.a&&!r.b);
},foot:'Two transactions read a shared initial snapshot and write disjoint rows. Serializable mode illustrates rejecting B; real engines may prevent or abort the schedule differently.'});

labs.locks=()=>({title:'A finished statement can keep a lock',state:{a:'idle',b:'idle',wait:0},controls:[B('a','A: BEGIN + UPDATE'),B('b','B: attempt UPDATE'),B('wait','Advance waiting by 1 second'),B('end','A: COMMIT / release')],actions:{a:s=>{if(s.a==='idle')s.a='open';},b:s=>{if(s.b==='done')return;s.b=s.a==='open'?'waiting':'done';},wait:s=>{if(s.b==='waiting')s.wait++;},end:s=>{if(s.a==='open'){s.a='committed';if(s.b==='waiting')s.b='done';}}},render:s=>{
 return flow([['Transaction A',s.a==='open'?'statement done · transaction open':s.a],['Row lock',s.a==='open'?'held by A':'free','purple'],['Transaction B',s.b,'blue']])+`<div class="db-lock-edge ${s.b==='waiting'?'blocked':''}">${s.b==='waiting'?'B waits → A owns the row':'No waiting edge'}</div>`+stats(['B waiting time',`${s.wait} s`],['A transaction open',s.a==='open'?'Yes':'No'],['B update complete',s.b==='done'?'Yes':'No'])+note('Start A, attempt B, advance time, then commit A. The row operation is tiny; the transaction lifetime creates the delay.');
},foot:'One exclusive row lock, serialized button actions, no deadlock cycle. B autocommits on acquiring the lock; A’s release also completes a waiting B.'});

labs.constraints=()=>({title:'Two clients both saw a free seat',state:{unique:false,rows:[],done:[],rejected:[]},controls:[T('unique','Enforce UNIQUE(seat_id)'),B('a','Client A inserts reservation'),B('b','Client B inserts reservation')],onChange:s=>{s.rows=[];s.done=[];s.rejected=[];},actions:{a:s=>Object.assign(s,reservation(s,'A',s.unique)),b:s=>Object.assign(s,reservation(s,'B',s.unique))},render:s=>{
 return flow([['Client A check','seat 7 was free'],['Client B check','seat 7 was free','blue']])+table(['seat_id','owner','Result'],s.rows.map(owner=>[7,owner,'committed']).concat(s.rejected.map(owner=>[7,owner,'uniqueness conflict'])))+stats(['Committed rows',s.rows.length],['Rejected attempts',s.rejected.length],['At most one owner',s.rows.length<=1?'Preserved':'VIOLATED'])+note(s.rows.length>1?'Both preliminary reads were true when made. Only atomic enforcement at insertion can arbitrate the competing reservations.':'Both availability checks happened before either insert. Try both inserts with and without the unique constraint.',s.rows.length>1);
},foot:'One seat, two clients, pre-completed checks, immediate commit per insert. Real uniqueness enforcement may wait for a competing transaction before success or conflict.'});

labs.wal=()=>({title:'Enforce write-ahead ordering',state:{stage:0,page:false,crashed:false,message:'Advance the transaction, or try flushing its page too early.'},controls:[B('step','Next commit milestone'),B('page','Attempt data-page flush'),B('crash','Crash machine')],actions:{step:s=>{if(!s.crashed){s.stage=Math.min(3,s.stage+1);s.message=['','Update and commit records staged in volatile WAL.','WAL including the commit record is durable.','Client receives acknowledgment.'][s.stage];}},page:s=>{if(s.crashed)return;if(s.stage<2)s.message='Blocked: the required WAL must be durable before this page is written.';else{s.page=true;s.message='The dirty page is safely written; its log was durable first.';}},crash:s=>{s.crashed=true;s.message=s.stage>=2?'Recovery preserves the committed new value, using WAL if the page was not written.':'The unsynced update is lost in this crash scenario.';}},render:s=>{
 const survived=s.stage>=2;
 return `<div class="db-durable-path">${[['Volatile WAL',s.stage>=1],['Durable WAL + commit',s.stage>=2],['Client acknowledged',s.stage>=3],['Data page on disk',s.page]].map(([label,done])=>`<div class="${done?'done':''}"><small>${done?'reached':'pending'}</small><strong>${label}</strong></div>`).join('')}</div>`+stats(['WAL durable',survived?'Yes':'No'],['Client knows success',s.stage>=3?'Yes':'No'],['After crash',s.crashed?survived?'New value':'Old value':'Not tested'])+note(s.message,s.crashed&&!survived);
},foot:'One transaction; staged WAL contains update + commit, successful sync makes both durable. New value is acknowledged synchronously; no replication, torn writes, or asynchronous commit.'});

labs.checkpoints=()=>({title:'Trade write frequency for replay distance',state:{interval:4,time:0,dirty:Array(6).fill(false),log:0,checkpoint:0,writes:0,count:0},controls:[R('interval','Checkpoint every N updates',2,12),B('step','Update next page'),B('run','Run 24 updates')],onChange:s=>{s.time=0;s.dirty=Array(6).fill(false);s.log=0;s.checkpoint=0;s.writes=0;s.count=0;},actions:{step:s=>Object.assign(s,checkpointStep(s)),run:s=>{for(let i=0;i<24;i++)Object.assign(s,checkpointStep(s));}},render:s=>{
 return `<div class="db-buffer-pool six">${s.dirty.map((dirty,i)=>`<div class="${dirty?'dirty':''}"><small>Page ${i+1}</small><strong>${dirty?'●':'○'}</strong><span>${dirty?'dirty':'clean'}</span></div>`).join('')}</div>`+flow([['Latest WAL position',s.log],['Checkpoint boundary',s.checkpoint,'purple'],['Redo suffix',`${s.log-s.checkpoint} records`,'blue']])+stats(['Checkpoints completed',s.count],['Data-page writes',s.writes],['Updates performed',s.time])+note('Run 24 updates at different checkpoint intervals, then step once more. Hot pages can absorb multiple updates before a later flush.');
},foot:'Six pages updated round-robin, WAL durable per update. Stop-the-world checkpoints flush all dirty pages; no background writes or full-page images. Frequency change resets the workload.'});

const redoRecords=[{lsn:1,value:110},{lsn:2,value:120},{lsn:3,value:90}];
labs.redo=()=>({title:'Replay a durable log prefix',state:{disk:0,durable:3,recovered:null,lastApplied:null},controls:[R('disk','Initial disk page LSN',0,3),R('durable','Durable WAL through LSN',1,3),B('replay','Replay durable records')],onChange:s=>{s.disk=Math.min(s.disk,s.durable);s.recovered=null;s.lastApplied=null;},actions:{replay:s=>{const initial=s.recovered||{lsn:s.disk,value:s.disk?redoRecords[s.disk-1].value:100};const result=redoPage(initial,redoRecords,s.durable);s.recovered=result.page;s.lastApplied=result.applied;}},render:s=>{
 const p=s.recovered||{lsn:s.disk,value:s.disk?redoRecords[s.disk-1].value:100};
 return `<div class="db-log-records">${redoRecords.map(r=>`<div class="${r.lsn<=s.durable?'durable':''}"><small>LSN ${r.lsn}</small><strong>value ← ${r.value}</strong><span>${r.lsn>s.durable?'not durable':r.lsn<=p.lsn?'already reflected':'needs redo'}</span></div>`).join('')}</div>`+flow([['Data page',`value ${p.value}`],['Page LSN',p.lsn,'purple'],['Last replay applied',s.lastApplied===null?'not run':`${s.lastApplied} records`,'blue']])+note('Replay twice. The second pass should do no work. Change the disk position to model some page updates having reached disk before the crash.');
},foot:'Committed, full-value after-images only. A page never starts beyond durable WAL. Real engines use resource-specific redo, transaction status, and corruption/torn-page protections.'});

labs.pitr=()=>({title:'Recover before the bad update',state:{target:2,gap:'None'},controls:[R('target','Replay through commit',0,4),C('gap','Missing archived segment',['None','1','2','3','4'])],render:s=>{
 const r=pitr(s.target,+s.gap||0);
 return `<div class="db-recovery-line"><div><small>Base backup</small><b>100 units</b></div>${r.events.map(e=>`<div class="${e.lsn===+s.gap?'missing':e.lsn<=s.target?'selected':''}"><small>Commit ${e.lsn}</small><b>${e.delta>0?'+':''}${e.delta}</b><span>${e.lsn===3?'bad update':e.lsn===+s.gap?'missing log':'logged change'}</span></div>`).join('')}</div>`+stats(['Target commit',s.target],['Recovery chain',r.reachable?'Complete':'BROKEN'],['Recovered units',r.reachable?r.value:'Unavailable'])+note(!r.reachable?'The required log sequence has a gap. A later segment cannot substitute for the missing history.':s.target>=3?'The destructive update is included in this recovery point. Stop at commit 2 to recover the earlier 130 units.':'This target excludes the later destructive update. Legitimate later changes would need separate reconciliation.',!r.reachable);
},foot:'Consistent base at commit 0, one archive segment per commit, single numeric record. Real backup consistency, WAL segment boundaries, timelines, and restore validation are omitted.'});

labs.vacuum=()=>({title:'Keep versions until readers release them',state:{oldest:15,vacuumed:false},controls:[R('oldest','Oldest supported snapshot',10,50,5),B('vacuum','Vacuum eligible versions')],onChange:s=>{s.vacuumed=false;},actions:{vacuum:s=>{s.vacuumed=true;}},render:s=>{
 const versions=vacuumVersions(s.oldest),eligible=versions.filter(v=>v.reclaimable).length;
 return `<div class="db-version-intervals">${versions.map((v,i)=>`<div class="${v.reclaimable?'eligible':''} ${s.vacuumed&&v.reclaimable?'reclaimed':''}"><span>Version ${i+1}</span><div><i style="left:${(v.born-10)/40*100}%;width:${((v.replaced===Infinity?50:v.replaced)-v.born)/40*100}%"></i><em style="left:${(s.oldest-10)/40*100}%"></em></div><small>${s.vacuumed&&v.reclaimable?'reclaimed':v.reclaimable?'eligible':v.replaced===Infinity?'current':'retained'}</small></div>`).join('')}</div><p class="small">Timeline: commit 10 → 50 · vertical line = oldest supported snapshot</p>`+stats(['Eligible old versions',eligible],['Reclaimed this run',s.vacuumed?eligible:0],['Current versions','1'])+note('An earlier snapshot holds the cleanup boundary back. Moving the slider starts a fresh retention scenario; vacuum only removes versions behind its safe horizon.');
},foot:'Commit-sequence intervals [born, replaced), fixed history, one oldest-reader bound. Real PostgreSQL transaction IDs, freezing, slots, and visibility horizons are more complex.'});

const compactionRuns=[[{key:'A',value:null,seq:5},{key:'B',value:20,seq:4}],[{key:'A',value:10,seq:2},{key:'B',value:15,seq:3}],[{key:'A',value:5,seq:1},{key:'C',value:30,seq:0}]];
labs.compaction=()=>({title:'Merge without resurrecting a deleted key',state:{all:false,drop:false,merged:false},controls:[T('all','Include the oldest run too'),T('drop','Drop tombstone from merge output'),B('merge','Perform compaction')],onChange:s=>{s.merged=false;},actions:{merge:s=>{s.merged=true;}},render:s=>{
 const inputs=compactionRuns.slice(0,s.all?3:2),output=compactRuns(inputs,s.drop),remaining=s.all?[]:compactionRuns.slice(2),after={mem:[],runs:[output,...remaining]},r=lsmRead(after,'A');
 return (s.merged?run('Merged output',output)+remaining.map(x=>run('Unmerged older run',x)).join(''):compactionRuns.map((x,i)=>run(`Input run ${i+1}${i===2&&!s.all?' · outside merge':''}`,x)).join(''))+stats(['Entries read by merge',inputs.flat().length],['Output entries',s.merged?output.length:'Not merged'],['Latest A after merge',s.merged?r.found?r.value:'Deleted':'Not merged'])+note(s.merged&&r.found?'Unsafe: discarding the tombstone exposed A = 5 in an unmerged older run. The deleted key has reappeared.':s.drop&&!s.all?'This choice is unsafe. Perform compaction to see why the marker still matters.':'The toy has no retained snapshots. Including all older data makes dropping the tombstone safe for latest-value reads only.',s.drop&&!s.all);
},foot:'Three immutable runs, sequence-number precedence, no snapshots. The unsafe toggle intentionally violates a compaction rule; real engines must preserve historical visibility and key-range coverage.'});

labs.partitions=()=>({title:'Prune by partition bounds',state:{start:3,end:5,usable:true},controls:[R('start','First month',1,12),R('end','Last month',1,12),T('usable','Planner can use partition-key bounds')],onChange:(s,key)=>{if(s.start>s.end){if(key==='start')s.end=s.start;else s.start=s.end;}},render:s=>{
 const partitions=partitionScan(s.start,s.end,s.usable),count=partitions.filter(p=>p.read).length;
 return `<div class="db-partitions">${partitions.map(p=>`<div class="${p.read?'read':''}"><small>Month ${p.month}</small><strong>${p.read?'scan':'skip'}</strong><span>100 pages</span></div>`).join('')}</div>`+stats(['Partitions visited',`${count} / 12`],['Pages scanned',count*100],['Rows returned',`${(s.end-s.start+1)*1000}`])+note(s.usable?'Only partitions whose bounds intersect the interval remain in the scan.':'The filter still returns the same rows, but this toy cannot use it to exclude any partition.');
},foot:'Twelve equal monthly partitions, 1,000 rows and 100 pages each, full-month range. No within-partition index, skew, empty partitions, or execution-time pruning.'});

const cases={
 'Wrong cardinality':{rows:[['Index scan estimate','100 rows'],['Actual rows','50,000 rows'],['Heap visits','50,000'],['Time waiting for locks','0 ms']],next:'Check predicate statistics',result:'The predicate matches a newly common value absent from stale statistics. A representative statistics refresh changes the next plan; verify actual I/O and latency.'},
 'Sort spill':{rows:[['Rows entering sort','1,000,000'],['Rows returned','100'],['Sort method','external merge'],['Temporary bytes','128 MiB']],next:'Inspect sort input and memory',result:'The sort consumes a wide input before applying the limit. Test a matching ordered access path or a safe memory budget, accounting for concurrent queries.'},
 'Open transaction':{rows:[['Query execution so far','waiting'],['Wait type','row lock'],['Blocker state','idle in transaction'],['Blocker age','180 seconds']],next:'Inspect blocker and transaction scope',result:'The blocker updated the row and then waited on a remote call without ending its transaction. Fix ownership and transaction scope; assess rollback impact before terminating sessions.'},
 'Cleanup debt':{rows:[['Dead versions','growing'],['Vacuum activity','running'],['Oldest reader','six hours old'],['Free reusable space','not increasing']],next:'Inspect retained snapshots',result:'A long reader pins the cleanup horizon. Resolve the unnecessary reader safely, then verify cleanup eligibility, reusable space, and workload latency.'}
};
const choices=Object.values(cases).map(c=>c.next);
labs.investigation=()=>({title:'Read the evidence before choosing a fix',state:{scenario:'Wrong cardinality',choice:choices[0],tested:false},controls:[C('scenario','Incident',Object.keys(cases)),C('choice','Next investigation',choices),B('test','Test this hypothesis')],onChange:s=>{s.tested=false;},actions:{test:s=>{s.tested=true;}},render:s=>{
 const c=cases[s.scenario],correct=s.choice===c.next;
 return `<div class="db-report"><span class="eyebrow">Execution evidence</span>${table(['Signal','Observation'],c.rows)}</div>`+flow([['Observe',s.scenario],['Investigate',s.choice,'blue'],['Result',s.tested?correct?'supported':'reconsider':'not tested','purple']])+note(s.tested?correct?c.result:`The strongest signals point elsewhere. Try: ${c.next.toLowerCase()}.`:'Choose the observation that can explain the cost or wait. A new index is only one possible intervention.',s.tested&&!correct);
},foot:'Curated incidents with synthetic metrics. No SQL is executed. A supported hypothesis still needs a representative before/after test and a safe change plan.'});

export const mountLab=(element,id)=>mountExperiment(element,labs[id]());
export const labIds=()=>Object.keys(labs);
export const createLab=id=>labs[id]();
